// Вкладка «Сообщество» в карточке тайтла: разделы (первый — «Пересказ аниме»), состояния, плеер ролика. Запуск: node design/prototype/community.test.js [shots]
const {chromium}=require('playwright');const path=require('path');
const IDX='file://'+path.join(__dirname,'index.html');const OUT=path.join(__dirname,'..','screenshots')+'/';const shots=process.argv[2]==='shots';
const UA='Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 Version/17.5 Mobile/15E148 Safari/604.1';
(async()=>{const b=await chromium.launch();let fails=0;
const V=[['ПК 1440×900',{viewport:{width:1440,height:900}},''],['телефон 390×844',{viewport:{width:390,height:844},isMobile:true,hasTouch:true,userAgent:UA},'phone-']];
for(const th of (shots?['dark','light']:['dark']))for(const [vn,o,k] of V){const ctx=await b.newContext({...o,colorScheme:th});const p=await ctx.newPage();const errs=[];p.on('pageerror',e=>errs.push(e.message));
 const ev=(f,a)=>p.evaluate(f,a);
 const click=async s=>{const l=p.locator(s).first();if(o.hasTouch)await l.tap({timeout:3000});else{await l.hover({force:true});await l.click({timeout:3000});}await p.waitForTimeout(200)};
 const demo=async v=>{await ev(v=>{const s=document.querySelector('#demoCommunity');s.value=v;s.dispatchEvent(new Event('change',{bubbles:true}))},v);await p.waitForTimeout(300)};
 const toTab=async()=>{await ev(()=>{const t=document.querySelector('[data-ttab=community]');t.scrollIntoView({block:'start'});document.querySelector('#main').scrollTop-=60})};
 const shot=async n=>{if(shots)await p.screenshot({path:OUT+n+'-'+k+th+'.png'})};
 const txt=s=>ev(s=>(document.querySelector(s)||{}).textContent||'',s);
 const cards=()=>ev(()=>document.querySelectorAll('#cmres .clip').length);
 const noHscroll=()=>ev(()=>document.documentElement.scrollWidth<=innerWidth&&document.querySelector('#main').scrollWidth<=document.querySelector('#main').clientWidth);
 const res=[];const T=async(n,f)=>{try{res.push([n,(await f())?'OK':'FAIL'])}catch(e){res.push([n,'FAIL '+e.message.split('\n')[0].slice(0,80)])}};
 await p.goto(IDX+'#catalog');await p.waitForTimeout(500);
 await T('В навигации нет «Сообщества» (Каталог, Списки, Друзья, Поиск), NavRail 56',async()=>{const n=await ev(()=>[...document.querySelectorAll('#rail a span')].map(s=>s.textContent).filter(Boolean));return !n.includes('Сообщество')&&n.slice(0,4).join()==='Каталог,Списки,Друзья,Поиск'&&await ev(()=>getComputedStyle(document.querySelector('#rail a')).width==='56px')});
 await T('Вкладка «Сообщество» последней, после «Похожие»',async()=>{await ev(()=>{S.titleId=2;S.titleTab='eps';location.hash='title'});await p.waitForTimeout(400);const t=await ev(()=>[...document.querySelectorAll('[data-ttab]')].map(b=>b.textContent));return t[t.length-1]==='Сообщество'&&t[t.length-2]==='Похожие'});
 await T('Разделы: «Пересказ аниме» первым, затем «Эдиты», «Обзоры», «Смешные моменты»',async()=>{await click('[data-ttab=community]');return (await ev(()=>[...document.querySelectorAll('[data-cmsect]')].map(b=>b.textContent).join('|')))==='Пересказ аниме|Эдиты|Обзоры|Смешные моменты'&&await ev(()=>document.querySelector('[data-cmsect=recap]').getAttribute('aria-pressed')==='true')});
 await T('«Пересказ аниме» по этому тайтлу: ролики, длительность, канал, «Открыть на YouTube», без бейджа языка',async()=>{await toTab();await p.waitForTimeout(200);await shot('211-title-community-recap');return (await cards())>=3&&await ev(()=>[...document.querySelectorAll('#cmres .clip')].every(c=>/^\d+:\d\d$/.test(c.querySelector('.dur').textContent)&&/Канал/.test(c.querySelector('.cap').textContent)&&c.querySelector('a.ext[target=_blank]')))&&await ev(()=>!document.querySelector('.lang')&&!/\b(RU|ENG)\b/.test(document.querySelector('#cmres').textContent))&&await noHscroll()});
 await T('«Эдиты»',async()=>{await click('[data-cmsect=edits]');await p.waitForTimeout(600);await toTab();await shot('220-title-community-edits');return (await cards())>=3});
 await T('Нет поиска тайтла и «Все тайтлы»',async()=>await ev(()=>!document.querySelector('#cmq, .cm-filter, [data-act=cmAll]')));
 await T('Пометка про пользовательские ролики',async()=>/Ролики с YouTube, созданы пользователями\. Не связаны с правообладателями/.test(await txt('.cm-note')));
 await T('«Обзоры» (скелетоны, потом ролики)',async()=>{await click('[data-cmsect=reviews]');const busy=await ev(()=>!!document.querySelector('#cmres [aria-busy=true]'));await p.waitForTimeout(600);await shot('212-title-community-reviews');return busy&&(await cards())>=3&&await ev(()=>document.querySelector('[data-cmsect=reviews]').getAttribute('aria-pressed')==='true')});
 await T('«Смешные моменты»',async()=>{await click('[data-cmsect=funny]');await p.waitForTimeout(600);return (await cards())>=3});
 await T('У тайтла без своих роликов вкладка не пустая',async()=>{await ev(()=>{S.titleId=10;render()});await p.waitForTimeout(200);return (await cards())>=3});
 await ev(()=>{S.titleId=2;CM.sect='recap';render()});await p.waitForTimeout(200);
 await T('Пусто',async()=>{await demo('empty');await toTab();await shot('213-title-community-empty');return /Роликов не нашлось/.test(await txt('#cmres .state'))});
 await T('Загрузка: скелетоны',async()=>{await demo('loading');await shot('214-title-community-loading');return await ev(()=>document.querySelectorAll('#cmres .skel.thumb').length===4)});
 await T('Лимит поиска',async()=>{await demo('quota');await shot('215-title-community-quota');return /Лимит поиска исчерпан, попробуйте завтра/.test(await txt('#cmres .state'))});
 await T('Ошибка сети → «Повторить»',async()=>{await demo('error');await shot('216-title-community-error');const ok=/Нет связи с YouTube/.test(await txt('#cmres .state'));await click('[data-act=cmRetry]');await p.waitForTimeout(1000);return ok&&(await cards())>=3});
 await T('Недоступно в регионе: пометка на миниатюре',async()=>{await demo('region');await ev(()=>{CM.sect='recap';render()});await p.waitForTimeout(200);await toTab();await shot('217-title-community-region');return await ev(()=>document.querySelectorAll('#cmres .clip.blocked .geo').length===1)});
 await T('Ролик из региона: объяснение, без «Открыть на YouTube»',async()=>{await click('.clip.blocked .thumb');await p.waitForTimeout(900);await shot('218-title-community-player-region');return await ev(()=>location.hash==='#player'&&/недоступен в вашем регионе/.test(document.querySelector('.yt-stage').textContent)&&!document.querySelector('.yt-bar a[target=_blank]'))});
 await T('«К роликам» → карточка, вкладка «Сообщество»',async()=>{await click('.yt-stage a[href="#title"]');await p.waitForTimeout(200);return await ev(()=>location.hash==='#title'&&document.querySelector('[data-ttab=community]').getAttribute('aria-selected')==='true')&&(await cards())>=3});
 await T('Обычный ролик: встроенный плеер, «Ролик пользователя · не от правообладателя», без комментариев',async()=>{await demo('ok');await click('.clip .thumb');const ld=/Открываем ролик/.test(await txt('.yt-stage'));await p.waitForTimeout(900);await shot('219-title-community-player');return ld&&await ev(()=>!!document.querySelector('#player.yt .yt-embed')&&!document.querySelector('.ytcom, [data-act=ytComments]')&&/Пересказ аниме/.test(document.querySelector('.yt-top .pl-title').textContent)&&/Ролик пользователя · не от правообладателя/.test(document.querySelector('.yt-bar').textContent))});
 await T('Назад из плеера → карточка; трейлер не сломан',async()=>{await click('.yt-top a[href="#title"]');const back=await ev(()=>location.hash==='#title'&&P.clip===null);await ev(()=>{P.trailer=true;location.hash='player'});await p.waitForTimeout(300);const ok=back&&/Трейлер/.test(await txt('.yt-top .pl-title'));await ev(()=>{S.titleTab='eps';location.hash='catalog'});return ok});
 const bad=res.filter(r=>r[1]!=='OK');fails+=bad.length;console.log(th,vn,bad.length?bad:'все '+res.length+' OK',errs);await ctx.close();}
await b.close();process.exitCode=fails?1:0;})();
